import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const f=JSON.parse('{"title":"数据源","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/sources.md","filePath":"zh/guide/sources.md","lastUpdated":1791997268000}'),d={name:"zh/guide/sources.md"};function l(n,e,s,h,i,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to &quot;数据源&quot;">​</a></h1><p>选择适合研究问题的文献索引，不同提供方的覆盖、元数据、访问要求和筛选能力并不相同。</p><h2 id="数据源目录" tabindex="-1">数据源目录 <a class="header-anchor" href="#数据源目录" aria-label="Permalink to &quot;数据源目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据源</th><th>社区版</th><th>在线版 BYOK</th><th>侧重</th></tr></thead><tbody><tr><td><a href="https://openalex.org/" target="_blank" rel="noreferrer">OpenAlex</a></td><td>建议配置 Key</td><td>必须配置 Key</td><td>广泛学术发现与引用扩展</td></tr><tr><td><a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a></td><td>无需 Key</td><td>无需 Key</td><td>科学预印本</td></tr><tr><td><a href="https://www.crossref.org/" target="_blank" rel="noreferrer">Crossref</a></td><td>无需 Key</td><td>无需 Key</td><td>DOI 与出版元数据</td></tr><tr><td><a href="https://www.semanticscholar.org/" target="_blank" rel="noreferrer">Semantic Scholar</a></td><td>Key 可选</td><td>必须配置 Key</td><td>论文与学术图谱元数据</td></tr><tr><td><a href="https://pubmed.ncbi.nlm.nih.gov/" target="_blank" rel="noreferrer">PubMed</a></td><td>NCBI Key 可选</td><td>必须配置 Key</td><td>生物医学与生命科学</td></tr><tr><td>Google Scholar / <a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper</a></td><td>必须配置 Serper Key</td><td>必须配置 Key</td><td>通过受支持 API 检索 Scholar</td></tr><tr><td>PaperHub 计算机顶会</td><td>无需 Key</td><td>无需 Key</td><td>PaperHub 提供的顶会集合</td></tr><tr><td><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">Web of Science Starter</a></td><td>需要 Clarivate Key</td><td>必须配置 Key</td><td>受支持的 WoS 集合</td></tr></tbody></table><p>PaperSeek 服务的数据源访问由 PaperSeek 管理。社区版按上表允许匿名访问或使用可选密钥；在线版 BYOK 是单独的访问策略，在设置中填写并保存数据源密钥；除 arXiv、Crossref、PaperHub 等无需密钥的数据源外，其余数据源（包括 OpenAlex、PubMed、Semantic Scholar）都必须提供密钥。模型 Key 与数据源 Key 并不通用。</p><h2 id="配置与测试数据源" tabindex="-1">配置与测试数据源 <a class="header-anchor" href="#配置与测试数据源" aria-label="Permalink to &quot;配置与测试数据源&quot;">​</a></h2><p>打开<strong>设置 → 数据源</strong>，点击来源所在行的<strong>配置</strong>或<strong>配置密钥</strong>，填写密钥和选项后点击<strong>保存</strong>。</p><p>此弹窗中的<strong>测试连接</strong>也会先保存当前密钥和选项，再测试。若保存失败，则不执行测试；保存成功后，即使测试失败或随后取消弹窗，也不会撤销保存。如需修改或清除已保存的密钥，请重新打开来源配置。列表中的<strong>测试</strong>和<strong>全部测试</strong>使用已配置的凭据，不会保存表单草稿。模型连接草稿的测试不会保存，详见<a href="./models">模型与排序</a>。</p><h2 id="申请凭据" tabindex="-1">申请凭据 <a class="header-anchor" href="#申请凭据" aria-label="Permalink to &quot;申请凭据&quot;">​</a></h2><ul><li><a href="https://openalex.org/settings/api" target="_blank" rel="noreferrer">OpenAlex API 设置</a>。</li><li><a href="https://www.semanticscholar.org/product/api#api-key-form" target="_blank" rel="noreferrer">Semantic Scholar Key 申请</a>。</li><li><a href="https://www.ncbi.nlm.nih.gov/books/NBK25497/" target="_blank" rel="noreferrer">NCBI API 指南</a>。</li><li><a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper 账户</a>。</li><li><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">WoS Starter 应用</a>。</li></ul><p>上游订阅和速率限制，与 PaperSeek 账户及积分分别管理。</p><h2 id="领域与分类" tabindex="-1">领域与分类 <a class="header-anchor" href="#领域与分类" aria-label="Permalink to &quot;领域与分类&quot;">​</a></h2><p>OpenAlex 使用受支持的学科选项，语义通道按支持的方式执行筛选；arXiv 使用 Category；WoS 学科与 WoS 数据库选择独立。其他来源使用文本领域提示。</p><p>限制领域可能排除跨学科文献，除非研究设计要求，否则可先不限制。</p><h2 id="元数据缺失" tabindex="-1">元数据缺失 <a class="header-anchor" href="#元数据缺失" aria-label="Permalink to &quot;元数据缺失&quot;">​</a></h2><p>记录可能没有摘要、年份、引用数或开放 PDF。信息缺失不是质量判断。</p><p>1.0.0-beta2 不再提供独立的跨源摘要补全或引用数补全开关。写综述时请选择摘要信息充分的文献。</p><h2 id="多-key-轮询" tabindex="-1">多 Key 轮询 <a class="header-anchor" href="#多-key-轮询" aria-label="Permalink to &quot;多 Key 轮询&quot;">​</a></h2><p>OpenAlex 与 Serper 支持用空白、逗号或分号分隔的 Key 池。请求会轮换起始 Key，鉴权失败与临时错误分别处理。</p><p>轮询不会改变提供方的条款，也不保证仍有余额，详见<a href="./../reference/configuration">配置参考</a>。</p>',20)])])}const b=t(d,[["render",l]]);export{f as __pageData,b as default};
